      newAngle: 'As mesmas estrelas, outro ângulo', stars: 'Estrelas', closest: 'Mais perto', farthest: 'Mais longe',
      size: 'Tamanho', temp: 'Temp.', surface: 'Superfície', day: 'Um dia', distance: 'Distância',
